    "faq-sync": {
      "id": "faq-sync",
      "title": "消息会同步吗",
      "description": "了解聊天记录在多设备间的同步方式。",
      "goal": "了解聊天记录在多设备间的同步方式。",
      "sections": [
        {
          "id": "answer",
          "title": "说明",
          "level": 2,
          "content": [
            {
              "type": "p",
              "text": "会。使用同一账号登录后，聊天记录、好友列表和大部分设置会保存在服务器，换电脑登录仍可查看历史消息。"
            },
            {
              "type": "p",
              "text": "同步速度取决于网络；较早的消息可能需要滚动加载。"
            }
          ]
        }
      ],
      "related": [
        "faq-network"
      ]
    },
    "faq-network": {
      "id": "faq-network",
      "title": "连不上或消息发不出",
      "description": "排查网络与登录相关问题。",
      "goal": "排查网络与登录相关问题。",
      "sections": [
        {
          "id": "请依次检查",
          "title": "请依次检查",
          "level": 2,
          "content": [
            {
              "type": "steps",
              "items": [
                "确认电脑已联网，可访问其他网站。",
                "查看 LinkX 顶部是否显示<strong>离线</strong>或连接失败提示。",
                "退出后重新登录，并完成验证码。",
                "若使用公司网络/VPN，确认未拦截 WebSocket 连接。"
              ]
            }
          ]
        },
        {
          "id": "faq",
          "title": "仍无法解决",
          "level": 2,
          "content": [
            {
              "type": "faq",
              "items": [
                {
                  "q": "下一步怎么办？",
                  "a": "请通过「如何提交问题反馈」向我们说明现象与截图。"
                }
              ]
            }
          ]
        }
      ],
      "related": [
        "submit-feedback",
        "faq-sync"
      ]
    },
